def evaluate(subject, dataset, now):
    if holds.active(subject=subject, dataset=dataset):
        return Decision('KEEP', reason='LEGAL_HOLD')
    out = []
    for col in dataset.subject_columns_and_payload():
        p = policy.for_class(col.data_class)
        age = now - record_time(subject, dataset)
        if age < p.min_retention and p.legal_basis == 'STATUTORY':
            out.append((col, 'KEEP_UNTIL', record_time + p.min_retention))
        else:
            out.append((col, p.method))        # delete | anonymise | crypto_shred
    return Decision('PARTIAL' if any(a[1] == 'KEEP_UNTIL' for a in out) else 'DELETE', out)

def run(req):
    disable_account(req.subject); sleep_until(req.grace_ends_at)
    if req.cancelled: return close('CANCELLED')
    tasks = planner.plan(req)                      # task_id = hash(req.id, dataset.id)
    for t in tasks:
        d = evaluator.evaluate(req.subject, t.dataset, now())
        if d.kind == 'KEEP': ledger.exempt(t, d); continue
        spawn(execute, t, d)
    await_all(); keys.shred(req.subject); denylist.add(req.subject)
    if scanner.scan_tier1(req.subject) == 0: ledger.close(req)
    else: incident('RESIDUAL_DATA', req)

def execute(t, d):
    for attempt in range(8):
        r = agent(t.store).delete(t, d)           # idempotent on t.id
        if r.ok: return ledger.done(t, r)
        sleep(min(6*HOUR, MINUTE * 2**attempt) * random.uniform(0.5, 1.5))
    escalate(t.dataset.owner, t, deadline=t.deadline)
